Here is the commit message:
ALSA: firewire-motu: add bounds check in put_user loop for
 DSP events

In the DSP event handling code, a put_user() loop copies event data.
When the user buffer size is not aligned to 4 bytes, it could overwrite
beyond the buffer boundary.

Fix by adding a bounds check before put_user().

Suggested-by: Takashi Iwai <tiwai@suse.de>
Fixes: 634ec0b2906e ("ALSA: firewire-motu: notify event for parameter change in register DSP model")
Signed-off-by: Junrui Luo <moonafterrain@outlook.com>
Link: https://patch.msgid.link/SYBPR01MB788112C72AF8A1C8C448B4B8AFA3A@SYBPR01MB7881.ausprd01.prod.outlook.com
Signed-off-by: Takashi Iwai <tiwai@suse.de>

Here is the root cause:
The bug occurs because the `put_user` loop in `hwdep_read` does not check whether the remaining buffer size is sufficient for the next 4-byte event before writing. The loop condition only ensures `consumed < count`, but if `count` is not a multiple of 4, the last write can overflow the user buffer. The patch adds a bounds check to prevent this.

Here is the patch:

 static long hwdep_read(struct snd_hwdep *hwdep, char __user *buf, long count,
 		       loff_t *offset)
 {
 	struct snd_motu *motu = hwdep->private_data;
 	DEFINE_WAIT(wait);
 	union snd_firewire_event event;

 	spin_lock_irq(&motu->lock);

 	while (!motu->dev_lock_changed && motu->msg == 0 && !has_dsp_event(motu)) {
 		prepare_to_wait(&motu->hwdep_wait, &wait, TASK_INTERRUPTIBLE);
 		spin_unlock_irq(&motu->lock);
 		schedule();
 		finish_wait(&motu->hwdep_wait, &wait);
 		if (signal_pending(current))
 			return -ERESTARTSYS;
 		spin_lock_irq(&motu->lock);
 	}

 	memset(&event, 0, sizeof(event));
 	if (motu->dev_lock_changed) {
 		event.lock_status.type = SNDRV_FIREWIRE_EVENT_LOCK_STATUS;
 		event.lock_status.status = (motu->dev_lock_count > 0);
 		motu->dev_lock_changed = false;
 		spin_unlock_irq(&motu->lock);

 		count = min_t(long, count, sizeof(event));
 		if (copy_to_user(buf, &event, count))
 			return -EFAULT;
 	} else if (motu->msg > 0) {
 		event.motu_notification.type = SNDRV_FIREWIRE_EVENT_MOTU_NOTIFICATION;
 		event.motu_notification.message = motu->msg;
 		motu->msg = 0;
 		spin_unlock_irq(&motu->lock);

 		count = min_t(long, count, sizeof(event));
 		if (copy_to_user(buf, &event, count))
 			return -EFAULT;
 	} else if (has_dsp_event(motu)) {
 		size_t consumed = 0;
 		u32 __user *ptr;
 		u32 ev;

 		spin_unlock_irq(&motu->lock);

 		// Header is filled later.
 		consumed += sizeof(event.motu_register_dsp_change);

 		while (consumed < count &&
 		       snd_motu_register_dsp_message_parser_copy_event(motu, &ev)) {
 			ptr = (u32 __user *)(buf + consumed);
-			if (put_user(ev, ptr))
+			if (consumed + sizeof(ev) > count || put_user(ev, ptr))
 				return -EFAULT;
 			consumed += sizeof(ev);
 		}

 		event.motu_register_dsp_change.type = SNDRV_FIREWIRE_EVENT_MOTU_REGISTER_DSP_CHANGE;
 		event.motu_register_dsp_change.count =
 			(consumed - sizeof(event.motu_register_dsp_change)) / 4;
 		if (copy_to_user(buf, &event,
 				 min_t(long, count, sizeof(event.motu_register_dsp_change))))
 			return -EFAULT;

 		count = min_t(long, count, consumed);
 	} else {
 		spin_unlock_irq(&motu->lock);

 		count = 0;
 	}

 	return count;
 }



